window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8cdb5e4c3d3fc84c"]={"versions": [{"id": "FIG-8cdb5e4c3d3fc84c", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation im AUTOSAR-Software-Component-Template (<code>AUTOSAR_TPS_SoftwareComponentTemplate</code>). Das Diagramm definiert die Struktur und Komposition einer <code>ApplicationRuleBasedValueSpecification</code>, die von der abstrakten Klasse <code>AbstractRuleBasedValueSpecification</code> erbt, zur regelbasierten Definition von Werten (insbesondere für Kennfelder, Achsen und Datencontainer) auf Anwendungsebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Klassen, Assoziationen und Kompositionen:</p>\n<ul class=\"fig-list\">\n<li><code>ApplicationRuleBasedValueSpecification</code> (spezialisiert <code>AbstractRuleBasedValueSpecification</code>):</li>\n<li>Attribut: <code>category :Identifier</code></li>\n<li>Komposition <code>+swAxisCont</code> zu <code>RuleBasedAxisCont</code> mit Multiplizität <code>0..* {ordered}</code>.</li>\n<li>Komposition <code>+swValueCont</code> zu <code>RuleBasedValueCont</code> mit Multiplizität <code>0..1</code>.</li>\n<li><code>RuleBasedAxisCont</code>:</li>\n<li>Attribute: <code>category :CalprmAxisCategoryEnum</code>, <code>swAxisIndex :AxisIndexType</code>.</li>\n<li>Assoziation <code>+unit</code> zu <code>Units::Unit</code> (<code>ARElement</code>) mit Multiplizität <code>0..1</code>.</li>\n<li>Komposition <code>+swArraysize</code> zu <code>DataDefProperties::ValueList</code> (<code>«atpMixed»</code>) mit Multiplizität <code>1</code>.</li>\n<li>Komposition <code>+ruleBasedValues</code> zu <code>RuleBasedValueSpecification</code> mit Multiplizität <code>1</code>.</li>\n<li><code>RuleBasedValueCont</code>:</li>\n<li>Assoziation <code>+unit</code> zu <code>Units::Unit</code> (<code>ARElement</code>) mit Multiplizität <code>0..1</code>.</li>\n<li>Komposition <code>+swArraysize</code> zu <code>DataDefProperties::ValueList</code> (<code>«atpMixed»</code>) mit Multiplizität <code>0..1</code>.</li>\n<li>Komposition <code>+ruleBasedValues</code> zu <code>RuleBasedValueSpecification</code> mit Multiplizität <code>1</code>.</li>\n<li><code>Units::Unit</code> (<code>ARElement</code>):</li>\n<li>Attribute: <code>factorSiToUnit :Float [0..1]</code>, <code>offsetSiToUnit :Float [0..1]</code>.</li>\n<li><code>DataDefProperties::ValueList</code> (<code>«atpMixed»</code>):</li>\n<li>Attribute: <code>v :Numerical</code>, unter <code>«atpVariation»</code> das Attribut <code>vf :Numerical [0..*] {ordered}</code>.</li>\n<li><code>RuleBasedValueSpecification</code>:</li>\n<li>Attribut: <code>rule :Identifier</code>.</li>\n<li>Komposition <code>+arguments</code> unter <code>«atpVariation»</code> (Binding-Time-Note: <code>vh.latestBindingTime = preCompileTime</code>) zu <code>RuleArguments</code> mit Multiplizität <code>1</code>.</li>\n<li><code>RuleArguments</code> (<code>«atpMixed»</code>):</li>\n<li>Attribute: <code>v :Numerical [0..1]</code>, <code>vt :VerbatimString [0..1]</code>, unter <code>«atpVariation»</code> das Attribut <code>vf :Numerical [0..1]</code>.</li>\n<li>Komposition <code>+vtf</code> unter <code>«atpVariation»</code> zu <code>NumericalOrText</code> mit Multiplizität <code>0..1</code>.</li>\n<li><code>NumericalOrText</code>:</li>\n<li>Attribute: <code>vt :String [0..1]</code>, unter <code>«atpVariation»</code> das Attribut <code>vf :Numerical [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodellstruktur ohne Verhaltensdiagrammelemente. Zur Generierung bzw. Auswertung der Werte evaluiert ein Generator oder Tool die durch das Attribut <code>rule</code> referenzierte Berechnungsregel unter Berücksichtigung der in <code>RuleArguments</code> übergebenen Argumente (<code>v</code>, <code>vt</code>, <code>vf</code>, <code>vtf</code>). Die Container <code>swAxisCont</code> und <code>swValueCont</code> kapseln jeweils die Achs- bzw. Wertedimensionen sowie zugehörige physikalische Einheiten (<code>Unit</code>) und Arraygrößen (<code>swArraysize</code>). Variantenauflösung (<code>«atpVariation»</code>) erfolgt spätestens zur Pre-Compile-Time (<code>vh.latestBindingTime = preCompileTime</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung erzwingt strenge Konsistenzbedingungen:</p>\n<ul class=\"fig-list\">\n<li>Falls Achsen definiert sind, sind sie über <code>RuleBasedAxisCont</code> geordnet (<code>{ordered}</code>) und über <code>swAxisIndex</code> indiziert.</li>\n<li>Einheiten (<code>Unit</code>) sind externe <code>ARElement</code>-Referenzen.</li>\n<li>Sowohl <code>RuleArguments</code> als auch <code>DataDefProperties::ValueList</code> sind als <code>«atpMixed»</code> gekennzeichnet und unterstützen gemischte Argumentstrukturen bzw. Zahlenlisten.</li>\n<li>Variationspunkte an den Assoziationen <code>+arguments</code> und <code>+vtf</code> sowie an Attributen (<code>vf</code>) unterliegen der spätesten Bindungszeit <code>preCompileTime</code>.</li>\n</ul>"}, {"id": "FIG-001b13f0481b7d91", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation im AUTOSAR-Software-Component-Template (<code>AUTOSAR_TPS_SoftwareComponentTemplate</code>). Das Diagramm definiert die Struktur und Komposition einer <code>ApplicationRuleBasedValueSpecification</code>, die von der abstrakten Klasse <code>AbstractRuleBasedValueSpecification</code> erbt, zur regelbasierten Definition von Werten (insbesondere für Kennfelder, Achsen und Datencontainer) auf Anwendungsebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Klassen, Assoziationen und Kompositionen:</p>\n<ul class=\"fig-list\">\n<li><code>ApplicationRuleBasedValueSpecification</code> (spezialisiert <code>AbstractRuleBasedValueSpecification</code>):</li>\n<li>Attribut: <code>category :Identifier</code></li>\n<li>Komposition <code>+swAxisCont</code> zu <code>RuleBasedAxisCont</code> mit Multiplizität <code>0..* {ordered}</code>.</li>\n<li>Komposition <code>+swValueCont</code> zu <code>RuleBasedValueCont</code> mit Multiplizität <code>0..1</code>.</li>\n<li><code>RuleBasedAxisCont</code>:</li>\n<li>Attribute: <code>category :CalprmAxisCategoryEnum</code>, <code>swAxisIndex :AxisIndexType</code>.</li>\n<li>Assoziation <code>+unit</code> zu <code>Units::Unit</code> (<code>ARElement</code>) mit Multiplizität <code>0..1</code>.</li>\n<li>Komposition <code>+swArraysize</code> zu <code>DataDefProperties::ValueList</code> (<code>«atpMixed»</code>) mit Multiplizität <code>1</code>.</li>\n<li>Komposition <code>+ruleBasedValues</code> zu <code>RuleBasedValueSpecification</code> mit Multiplizität <code>1</code>.</li>\n<li><code>RuleBasedValueCont</code>:</li>\n<li>Assoziation <code>+unit</code> zu <code>Units::Unit</code> (<code>ARElement</code>) mit Multiplizität <code>0..1</code>.</li>\n<li>Komposition <code>+swArraysize</code> zu <code>DataDefProperties::ValueList</code> (<code>«atpMixed»</code>) mit Multiplizität <code>0..1</code>.</li>\n<li>Komposition <code>+ruleBasedValues</code> zu <code>RuleBasedValueSpecification</code> mit Multiplizität <code>1</code>.</li>\n<li><code>Units::Unit</code> (<code>ARElement</code>):</li>\n<li>Attribute: <code>factorSiToUnit :Float [0..1]</code>, <code>offsetSiToUnit :Float [0..1]</code>.</li>\n<li><code>DataDefProperties::ValueList</code> (<code>«atpMixed»</code>):</li>\n<li>Attribute: <code>v :Numerical</code>, unter <code>«atpVariation»</code> das Attribut <code>vf :Numerical [0..*] {ordered}</code>.</li>\n<li><code>RuleBasedValueSpecification</code>:</li>\n<li>Attribute: <code>maxSizeToFill :Integer [0..1]</code>, <code>rule :Identifier</code>.</li>\n<li>Komposition <code>+arguments</code> unter <code>«atpVariation»</code> (Binding-Time-Note: <code>vh.latestBindingTime = preCompileTime</code>) zu <code>RuleArguments</code> mit Multiplizität <code>1</code>.</li>\n<li><code>RuleArguments</code> (<code>«atpMixed»</code>):</li>\n<li>Attribute: <code>v :Numerical [0..1]</code>, <code>vt :VerbatimString [0..1]</code>, unter <code>«atpVariation»</code> das Attribut <code>vf :Numerical [0..1]</code>.</li>\n<li>Komposition <code>+vtf</code> unter <code>«atpVariation»</code> zu <code>NumericalOrText</code> mit Multiplizität <code>0..1</code>.</li>\n<li><code>NumericalOrText</code>:</li>\n<li>Attribute: <code>vt :String [0..1]</code>, unter <code>«atpVariation»</code> das Attribut <code>vf :Numerical [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodellstruktur ohne Verhaltensdiagrammelemente. Zur Generierung bzw. Auswertung der Werte evaluiert ein Generator oder Tool die durch das Attribut <code>rule</code> referenzierte Berechnungsregel unter Berücksichtigung der in <code>RuleArguments</code> übergebenen Argumente (<code>v</code>, <code>vt</code>, <code>vf</code>, <code>vtf</code>). Die Container <code>swAxisCont</code> und <code>swValueCont</code> kapseln jeweils die Achs- bzw. Wertedimensionen sowie zugehörige physikalische Einheiten (<code>Unit</code>) und Arraygrößen (<code>swArraysize</code>). Variantenauflösung (<code>«atpVariation»</code>) erfolgt spätestens zur Pre-Compile-Time (<code>vh.latestBindingTime = preCompileTime</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung erzwingt strenge Konsistenzbedingungen:</p>\n<ul class=\"fig-list\">\n<li>Falls Achsen definiert sind, sind sie über <code>RuleBasedAxisCont</code> geordnet (<code>{ordered}</code>) und über <code>swAxisIndex</code> indiziert.</li>\n<li>Einheiten (<code>Unit</code>) sind externe <code>ARElement</code>-Referenzen.</li>\n<li>Sowohl <code>RuleArguments</code> als auch <code>DataDefProperties::ValueList</code> sind als <code>«atpMixed»</code> gekennzeichnet und unterstützen gemischte Argumentstrukturen bzw. Zahlenlisten.</li>\n<li>Variationspunkte an den Assoziationen <code>+arguments</code> und <code>+vtf</code> sowie an Attributen (<code>vf</code>) unterliegen der spätesten Bindungszeit <code>preCompileTime</code>.</li>\n</ul>"}], "trans": [{"from": "FIG-8cdb5e4c3d3fc84c", "to": "FIG-001b13f0481b7d91", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>In Klasse <code>RuleBasedValueSpecification</code> wurde das optionale Attribut <code>maxSizeToFill :Integer [0..1]</code> ergänzt.</li>\n</ul>"}]};
